#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/profit_directed_recursion_v16_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/recursive_improvement_controller.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/profit_directed_capability_priority.py
echo "" | base64 -d > "$PREFIX/tmp/companyos_profit_directed_v16_patch.py"
python "$PREFIX/tmp/companyos_profit_directed_v16_patch.py"
rm -f "$PREFIX/tmp/companyos_profit_directed_v16_patch.py"

echo "" | base64 -d > scripts/companyos_profitcapctl
chmod +x scripts/companyos_profitcapctl
echo "" | base64 -d > tests/test_profit_directed_capability_priority_v16.py

echo "[1/8] Compile"
python -m py_compile companyos/runtime/profit_directed_capability_priority.py companyos/runtime/recursive_improvement_controller.py tests/test_profit_directed_capability_priority_v16.py

echo "[2/8] Priority tests"
python -m unittest tests.test_profit_directed_capability_priority_v16 -v

echo "[3/8] Rank current guarded requests"
scripts/companyos_profitcapctl once | tee .companyos_runtime/profit_directed_capability_priority_v16.json

echo "[4/8] Show ranked status"
scripts/companyos_profitcapctl status || true

echo "[5/8] Run one profit-directed recursive cycle"
scripts/companyos_recursive_ctl once | tee .companyos_runtime/recursive_profit_directed_v16_cycle.json || true

echo "[6/8] Refresh feedback + inventory"
scripts/companyos_feedbackctl once || true
scripts/companyos_expandctl inventory || true

echo "[7/8] Commit/push"
git add companyos/runtime/profit_directed_capability_priority.py companyos/runtime/recursive_improvement_controller.py scripts/companyos_profitcapctl tests/test_profit_directed_capability_priority_v16.py
git diff --cached --quiet || git commit -m "Prioritize recursive capability growth by profit execution impact"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[8/8] Verify"
echo "===== PROFIT-DIRECTED CAPABILITY PRIORITY ====="
scripts/companyos_profitcapctl status || true
echo "===== RECURSIVE CONTROLLER ====="
scripts/companyos_recursive_ctl status || true
echo "===== REQUESTS ====="
scripts/companyos_compoundctl requests || true
echo "===== INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_PROFIT_DIRECTED_RECURSION_V16=PASS"
